package com.agriconnect.controller; import com.agriconnect.model.*; import com.agriconnect.repository.*; import jakarta.servlet.http.HttpSession; import org.springframework.stereotype.Controller; import org.springframework.ui.Model; import org.springframework.web.bind.annotation.*; import org.springframework.web.servlet.mvc.support.RedirectAttributes; import java.math.BigDecimal; import java.util.List; @Controller public class MarketplaceController {private final ProductRepository p; private final OrderRepository o; public MarketplaceController(ProductRepository p,OrderRepository o){this.p=p;this.o=o;} private AppUser u(HttpSession s){return (AppUser)s.getAttribute("user");} @ModelAttribute("currentUser") public AppUser current(HttpSession s){return u(s);} @GetMapping("/") public String home(Model m){m.addAttribute("products",p.findAll());m.addAttribute("productCount",p.count());return "index";} @GetMapping("/products") public String list(@RequestParam(required=false) String q,Model m){m.addAttribute("products",q==null||q.isBlank()?p.findAll():p.findByNameContainingIgnoreCaseOrCategoryContainingIgnoreCase(q,q));m.addAttribute("q",q==null?"":q);return "products";} @GetMapping("/products/{id}") public String detail(@PathVariable Long id,Model m){m.addAttribute("product",p.findById(id).orElseThrow());return "product-detail";} @GetMapping("/dashboard") public String dash(HttpSession s,Model m){AppUser x=u(s);if(x==null)return "redirect:/login";m.addAttribute("user",x);m.addAttribute("myProducts",x.getRole()==AppUser.Role.FARMER?p.findByFarmerId(x.getId()):List.of());m.addAttribute("myOrders",x.getRole()==AppUser.Role.BUYER?o.findByBuyerIdOrderByCreatedAtDesc(x.getId()):o.findByProductFarmerIdOrderByCreatedAtDesc(x.getId()));return "dashboard";} @GetMapping("/products/new") public String form(HttpSession s,Model m){if(u(s)==null)return "redirect:/login";if(u(s).getRole()!=AppUser.Role.FARMER)return "redirect:/dashboard";m.addAttribute("product",new Product());return "product-form";} @PostMapping("/products") public String create(@ModelAttribute Product x,HttpSession s,RedirectAttributes r){AppUser a=u(s);if(a==null)return "redirect:/login";if(a.getRole()!=AppUser.Role.FARMER)return "redirect:/dashboard";x.setFarmer(a);p.save(x);r.addFlashAttribute("success","Listing created.");return "redirect:/dashboard";} @GetMapping("/products/{id}/edit") public String edit(@PathVariable Long id,HttpSession s,Model m){AppUser a=u(s);if(a==null)return "redirect:/login";Product x=p.findById(id).orElseThrow();if(a.getRole()!=AppUser.Role.FARMER||!x.getFarmer().getId().equals(a.getId()))return "redirect:/dashboard";m.addAttribute("product",x);return "product-form";} @PostMapping("/products/{id}/edit") public String update(@PathVariable Long id,@ModelAttribute Product x,HttpSession s,RedirectAttributes r){AppUser a=u(s);if(a==null)return "redirect:/login";Product old=p.findById(id).orElseThrow();if(a.getRole()!=AppUser.Role.FARMER||!old.getFarmer().getId().equals(a.getId()))return "redirect:/dashboard";x.setId(id);x.setFarmer(a);p.save(x);r.addFlashAttribute("success","Listing updated.");return "redirect:/dashboard";} @PostMapping("/products/{id}/delete") public String delete(@PathVariable Long id,HttpSession s){AppUser a=u(s);if(a==null)return "redirect:/login";Product x=p.findById(id).orElseThrow();if(a.getRole()==AppUser.Role.FARMER&&x.getFarmer().getId().equals(a.getId()))p.delete(x);return "redirect:/dashboard";} @PostMapping("/orders/{id}") public String order(@PathVariable Long id,@RequestParam int quantity,HttpSession s,RedirectAttributes r){AppUser buyer=u(s);if(buyer==null)return "redirect:/login";if(buyer.getRole()!=AppUser.Role.BUYER)return "redirect:/products/"+id;Product x=p.findById(id).orElseThrow();if(quantity<1||quantity>x.getQuantity()){r.addFlashAttribute("error","Quantity unavailable.");return "redirect:/products/"+id;}AgriOrder a=new AgriOrder();a.setBuyer(buyer);a.setProduct(x);a.setQuantity(quantity);a.setTotalPrice(x.getPrice().multiply(BigDecimal.valueOf(quantity)));x.setQuantity(x.getQuantity()-quantity);p.save(x);o.save(a);r.addFlashAttribute("success","Order placed.");return "redirect:/dashboard";} @PostMapping("/orders/{id}/status") public String status(@PathVariable Long id,@RequestParam String status,HttpSession s){AppUser a=u(s);if(a==null)return "redirect:/login";AgriOrder x=o.findById(id).orElseThrow();if(a.getRole()==AppUser.Role.FARMER&&x.getProduct().getFarmer().getId().equals(a.getId())&&List.of("CONFIRMED","COMPLETED","CANCELLED").contains(status)){x.setStatus(status);o.save(x);}return "redirect:/dashboard";} @GetMapping("/about") public String about(){return "about";}}